local ArrayField = loadstring(game:HttpGet('https://raw.githubusercontent.com/UI-Interface/ArrayField/main/Source.lua'))()

local Window = ArrayField:CreateWindow({
   Name = "Shoot Run Sim",
   LoadingTitle = "Shoot Run sim",
   LoadingSubtitle = "By SimpleScripter",
   ConfigurationSaving = {
      Enabled = true,
      FolderName = nil, -- Create a custom folder for your hub/game
      FileName = "ArrayField"
   },
   Discord = {
      Enabled = false,
      Invite = "noinvitelink", -- The Discord invite code, do not include discord.gg/. E.g. discord.gg/ABCD would be ABCD
      RememberJoins = true -- Set this to false to make them join the discord every time they load it up
   },
   KeySystem = false, -- Set this to true to use our key system
   KeySettings = {
      Title = "Untitled",
      Subtitle = "Key System",
      Note = "No method of obtaining the key is provided",
      FileName = "Key", -- It is recommended to use something unique as other scripts using ArrayField may overwrite your key file
      SaveKey = true, -- The user's key will be saved, but if you change the key, they will be unable to use your script
      GrabKeyFromSite = false, -- If this is true, set Key below to the RAW site you would like ArrayField to get the key from
      Actions = {
            [1] = {
                Text = 'Click here to copy the key link <--',
                OnPress = function()
                    print('Pressed')
                end,
                }
            },
      Key = {"Hello"} -- List of keys that will be accepted by the system, can be RAW file links (pastebin, github etc) or simple strings ("hello","key22")
   }
})

local Tab = Window:CreateTab("Main", 4483362458) -- Title, Image

local Button = Tab:CreateButton({
   Name = "Inf wins",
   Interact = 'Click',
   Callback = function()
   local args = {
    [1] = {
        ["Boost"] = 30,
        ["Png"] = "rbxassetid://18223271262",
        ["Name"] = "Deep Orange Shotgun",
        ["Cost"] = -100000000000000
    },
    [2] = "SEcrEt"
}

game:GetService("ReplicatedStorage").RemoteFun.BuyGloves:InvokeServer(unpack(args))
   end,
})

local Input = Tab:CreateInput({
   Name = "Input Wins",
   PlaceholderText = "",
   NumbersOnly = true, -- If the user can only type numbers. Remove or set to false if none.
   CharacterLimit = 100, --max character limit. Remove or set to false
   OnEnter = true, -- Will callback only if the user pressed ENTER while being focused on the the box.
   RemoveTextAfterFocusLost = false, -- Speaks for itself.
   Callback = function(Text)
   local args = {
    [1] = {
        ["Boost"] = 30,
        ["Png"] = "rbxassetid://18223271262",
        ["Name"] = "Deep Orange Shotgun",
        ["Cost"] = -Text
    },
    [2] = "SEcrEt"
}

game:GetService("ReplicatedStorage").RemoteFun.BuyGloves:InvokeServer(unpack(args))
   end,
})

